INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://smartboxaac.com/ukie/news/meet-sarah/', 'AI rebuilds Sarah Ezekiel''s voice from seconds of old video', 'Sarah Ezekiel, an artist from London, was diagnosed with motor neurone disease in 2000 and lost her speech. Assistive technology company Smartbox and ElevenLabs used AI to recreate her voice from a single line of speech in an old home video, a clip reported as eight seconds long. Her children heard her speak in a natural voice, cockney accent included, for the first time, and she said she almost cried when she first heard it.', 'helping_people_now', '["accessibility", "voice"]', 'sarah-ezekiel-voice-restored', 'accessibility', 'voice', 24, 'AI rebuilt Sarah''s own voice from a single line in an old home video, and her children heard her speak naturally for the first time.', '["The eight seconds and the cockney accent come from press reports, not the company''s own page."]', '["https://smartboxaac.com/ukie/news/meet-sarah/", "https://nrtimes.co.uk/vhs-clip-gives-mnd-patient-back-her-natural-speech-nra25/"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://today.ucsd.edu/story/alert-california', 'AI-watched cameras spot California wildfires early', 'ALERTCalifornia, led by UC San Diego, watches the state''s highest fire-risk areas around the clock with more than 1,000 cameras. AI scans the feeds for signs of fire and alerts trained staff, who confirm before firefighters respond; it was rolled out to all 21 CAL FIRE units in September 2023. The programme''s director said that in 2025 it alerted fire officials before 911 callers did in more than half of about 3,600 incidents.', 'helping_people_now', '["climate_and_nature", "vision"]', 'california-wildfire-cameras', 'climate_and_nature', 'vision', 23, 'AI watches more than 1,000 cameras at once, day and night, and alerts staff to smoke so firefighters can get moving early.', '["''Before 911 callers in more than half of incidents'' is the programme director''s own figure and hasn''t been audited.", "Trained staff confirm every alert before firefighters respond."]', '["https://today.ucsd.edu/story/alert-california", "https://www.route-fifty.com/public-safety/2026/07/what-california-has-learned-ai-enabled-early-wildfire-detection-system/414566/"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://bemyeyes.com/blog/announcing-be-my-ai', 'Be My AI describes the world for blind people', 'In 2023 the free Be My Eyes app added Be My AI: a blind or low-vision user takes a photo, gets a detailed description and can ask follow-up questions, with human volunteers still on hand. More than 19,000 blind and low-vision people tested it first. In a 2023 survey by a US research centre on blindness, nearly half of Be My Eyes users had tried it and all but one of the 76 who commented were positive, though a few noted it can be inconsistent.', 'helping_people_now', '["accessibility", "language model"]', 'be-my-ai-describes-photos', 'accessibility', 'language model', 23, 'A blind person can find out what is in front of them and ask follow-up questions, for free, without waiting for a sighted person.', '["A few users said it can be inconsistent. Human volunteers are still available in the app."]', '["https://bemyeyes.com/blog/announcing-be-my-ai", "https://www.afb.org/aw/fall2024/ai-usage-research"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://climate.uchicago.edu/news/artificial-intelligence-is-helping-indian-farmers-adapt-to-climate-change-forecast-accurately-predicting-an-unusual-monsoon-season-reached-38-million/', 'AI monsoon forecasts reach 38 million farmers in India', 'In summer 2025 India''s Ministry of Agriculture and Farmers'' Welfare sent AI-based monsoon forecasts by text message to about 38 million farmers, up to four weeks before the rains arrived. The forecasts, built with teams at the University of Chicago and UC Berkeley, correctly predicted that the monsoon would stall for about three weeks after an early start. Odisha''s state government reached nearly a million more farmers by voice message.', 'helping_people_now', '["everyday_life", "forecasting"]', 'monsoon-forecasts-for-farmers', 'everyday_life', 'forecasting', 23, '38 million farmers got up to four weeks'' notice by text, and the forecast correctly called a three-week stall in the rains.', '[]', '["https://climate.uchicago.edu/news/artificial-intelligence-is-helping-indian-farmers-adapt-to-climate-change-forecast-accurately-predicting-an-unusual-monsoon-season-reached-38-million/", "https://news.berkeley.edu/2025/09/16/ai-revolutionizes-weather-prediction-to-help-farmers-in-india/"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://peregrinefund.org/news-release/research-shows-identiflight-camera-technology-greatly-reduces-wind-turbine-eagle', 'AI cameras that pause wind turbines cut eagle deaths at a Wyoming wind farm', 'At the Top of the World wind farm in Wyoming, cameras watch the sky, software works out whether a flying object is an eagle, and individual turbines are slowed or stopped when one is at risk. A study in the Journal of Applied Ecology found eagle deaths there fell by 63% after the system went in, while deaths at a nearby wind farm without it rose by 113%. Set against that neighbour, the death rate was 82% lower.', 'helping_people_now', '["climate_and_nature", "vision"]', 'eagle-spotting-cameras-wyoming-wind-farm', 'climate_and_nature', 'vision', 23, 'The system uses machine learning to tell eagles from other flying things in time to stop the right turbine, so clean power and big birds of prey get in each other''s way less.', '["Deaths were reduced, not ended: the authors say it is not a complete solution.", "The 82% figure is relative to the comparison site 15 km away; the drop at the wind farm itself was 63%.", "One wind farm in Wyoming. A 2022 re-analysis by the same authors answered critics and again found a large fall, but with a very wide range of uncertainty (I saw this in a search listing only, the page would not open).", "The camera maker IdentiFlight and the site owner Duke Energy Renewables took part in the announcement; the study itself was by The Peregrine Fund, Western EcoSystems Technology and the US Geological Survey.", "The paper''s summary says cameras ''detect and classify'' birds; the words machine learning and neural networks come from The Peregrine Fund''s release."]', '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:10.1111/1365-2664.13831&resultType=core&format=json", "https://peregrinefund.org/news-release/research-shows-identiflight-camera-technology-greatly-reduces-wind-turbine-eagle"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.downtoearth.org.in/wildlife-biodiversity/ai-enabled-system-successful-in-preventing-elephant-train-collisions-on-kerala-tamil-nadu-border', 'AI cameras warn trains when elephants are near the tracks in Tamil Nadu', 'On a seven kilometre stretch of railway through forest near Madukkarai, on the Tamil Nadu and Kerala border, heat-sensing cameras on 12 towers use AI to spot elephants approaching the line and alert forest and railway staff. The system was officially switched on in February 2024. In July 2026 the state''s top forest official, Supriya Sahu, said it had seen 9,481 safe elephant crossings, with trains slowed or stopped 3,821 times and no elephant killed on those tracks in two and a half years.', 'helping_people_now', '["climate_and_nature", "vision"]', 'ai-cameras-stop-trains-for-elephants-tamil-nadu', 'climate_and_nature', 'vision', 23, 'The AI spots elephants in the dark early enough for train drivers to slow down, on a stretch where a local conservationist counts 11 elephants killed by trains since 2008.', '["All the results are the Tamil Nadu government''s own figures, given by Supriya Sahu in a social media post and reported by DT Next and Down To Earth. There is no independent study.", "The zero deaths claim covers only the monitored stretch near Madukkarai, not the whole line or other railways.", "The figure of 11 earlier deaths comes from a conservation activist, S Guruvayurappan, quoted by Down To Earth.", "People still do the work: forest staff and control room workers act on the alerts."]', '["https://www.downtoearth.org.in/wildlife-biodiversity/ai-enabled-system-successful-in-preventing-elephant-train-collisions-on-kerala-tamil-nadu-border", "https://www.dtnext.in/news/tamilnadu/ai-powered-elephant-alert-system-enables-9481-safe-crossings-records-zero-train-track-deaths"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.wfae.org/united-states-world/2025-11-29/as-the-2025-atlantic-hurricane-season-ends-the-future-of-forecasting-is-ai', 'An AI model gave the most accurate hurricane forecasts of the 2025 Atlantic season', 'Google DeepMind''s AI hurricane model was the most accurate forecast model of the 2025 Atlantic season for both where storms went and how strong they got, according to an analysis by James Franklin, a former branch chief at the US National Hurricane Center. The centre''s forecasters cited it in many of their public forecast discussions, especially for Hurricane Melissa. About a week before Melissa hit Jamaica as a Category 5 storm in late October, when other models disagreed, the AI model correctly predicted both its path and its strength.', 'helping_people_now', '["climate_and_nature", "forecasting"]', 'ai-hurricane-model-best-of-2025-season', 'climate_and_nature', 'forecasting', 23, 'Earlier AI weather models were poor at judging a hurricane''s strength, and this one got both path and strength right, giving forecasters better guidance to warn people in a storm''s way.', '["Melissa was the strongest storm ever to hit Jamaica and killed dozens of people. This is a story about a better warning, not a happy ending.", "One season only, and the ranking is James Franklin''s analysis as reported by NPR, not an official National Hurricane Center verification report.", "Human forecasters still write the official forecast. NPR''s experts say AI will not replace physics-based models or forecasters'' judgement.", "Do not say the AI saved lives or was the reason people evacuated. The source does not say that.", "The model is Google''s, built with National Hurricane Center and Colorado State University scientists. The independent source here is NPR."]', '["https://www.wfae.org/united-states-world/2025-11-29/as-the-2025-atlantic-hurricane-season-ends-the-future-of-forecasting-is-ai"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.tokyoupdates.metro.tokyo.lg.jp/en/post-1641/', 'A Tokyo railway returned nearly three times as many lost items after AI took over the lost property desk', 'Keio, a railway company in Tokyo with 69 stations, gets about 500 enquiries a day about lost property. Since 2023 its staff have photographed each found item, and AI from the Tokyo start-up Find records its colour, shape and size so owners can search by picture and chat in four languages. In Keio''s trial the share of items returned to their owners nearly tripled and enquiries by phone and at station counters fell by about a third.', 'helping_people_now', '["everyday_life", "vision"]', 'japan-ai-lost-property-keio', 'everyday_life', 'vision', 23, 'The AI describes and matches items from a photo, so a plain umbrella or wallet gets back to its owner and station staff spend about a minute logging it, not ten.', '["The results come from Keio''s trial as reported on the Tokyo government''s news site; exact return rates were not confirmed", "The ten minutes to one minute figure is for umbrellas", "33 companies use it; do not say all of Japan"]', '["https://www.tokyoupdates.metro.tokyo.lg.jp/en/post-1641/"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.spokesman.com/stories/2026/mar/22/these-people-used-ai-to-help-find-their-lost-pets', 'AI photo matching has reunited more than 200,000 lost pets with their owners in the US', 'Love Lost is a free US database run by the charity Petco Love, where owners upload a photo of a missing pet and AI compares its face, coat and markings with photos from about 3,000 shelters and from social media. The database says it has reunited more than 200,000 pets and owners since 2021. When Millie, a dog who slipped her collar in Manhattan in 2024, was hit by a car and taken to a vet in New Jersey, the system matched her photo and her owner Michael Bown had her back within about 15 hours.', 'helping_people_now', '["everyday_life", "vision"]', 'petco-love-lost-ai-reunites-pets', 'everyday_life', 'vision', 23, 'The AI recognises one animal among huge numbers of shelter and social media photos, which gets pets home that paper posters would not have found.', '["The 200,000 figure is the charity''s own count, reported by the Washington Post", "Petco Love is linked to the pet shop chain Petco", "Animal charities say it does not replace microchipping"]', '["https://www.spokesman.com/stories/2026/mar/22/these-people-used-ai-to-help-find-their-lost-pets", "https://www.cbsnews.com/news/ai-lost-pets-petco-love-facial-recognition"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.england.nhs.uk/2025/12/life-changing-ai-support-helping-stroke-patients-get-a-second-chance/', 'AI brain-scan reading in every stroke centre in England', 'AI tools that read brain scans and flag signs of a major stroke within minutes were rolled out to all stroke centres in England in summer 2024. A study in The Lancet Digital Health found that at the 26 hospitals evaluated, the share of patients getting clot-removing surgery doubled from 2.3% to 4.6%. NHS England also reported transfers to specialist centres happening 64 minutes sooner at primary stroke centres.', 'helping_people_now', '["health", "vision"]', 'stroke-scans-england', 'health', 'vision', 22, 'The AI reads the brain scan in minutes, and where it was studied twice as many patients had the clot removed and transfers to specialists were about an hour faster.', '["An observational study at 26 hospitals. The doubling is an association, not proof the AI caused it."]', '["https://www.england.nhs.uk/2025/12/life-changing-ai-support-helping-stroke-patients-get-a-second-chance/", "https://doi.org/10.1016/j.landig.2025.100927"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://health.ucdavis.edu/news/headlines/new-brain-computer-interface-allows-man-with-als-to-speak-again/2024/08', 'Brain implant and AI let a man with ALS speak again', 'Casey Harrell, a 45-year-old man whose speech had been badly damaged by ALS, had sensors implanted in his brain as part of the BrainGate2 clinical trial at UC Davis Health. Machine learning turns the brain activity of his attempts to speak into words on a screen, read aloud in a voice built to sound like his own before the illness. The system held 97.5% accuracy over more than eight months, according to results in the New England Journal of Medicine.', 'in_a_trial', '["accessibility", "voice"]', 'casey-harrell-speaks-again', 'accessibility', 'voice', 22, 'Machine learning turns Casey''s attempts to speak into words, read aloud in a voice built to sound like his own, with 97.5% accuracy.', '["One person, in a clinical trial, with sensors implanted in his brain."]', '["https://health.ucdavis.edu/news/headlines/new-brain-computer-interface-allows-man-with-als-to-speak-again/2024/08", "https://doi.org/10.1056/NEJMoa2314132"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.biospace.com/press-releases/feinstein-institutes-technology-that-restores-movement-and-sensation-after-paralysis-featured-in-nature-medicine', 'Brain implants and AI let a paralysed New York man feed himself and feel his sister''s hand', 'Keith Thomas, from Massapequa in New York, was paralysed from the chest down in a diving accident in 2020. In a trial at the Feinstein Institutes, surgeons put five small sensors in his brain, and AI reads the movements he intends and sends signals to his arm muscles, while sensors on his hand send touch back to his brain. Results published in Nature Medicine in July 2026 report that he now feeds himself, drinks from a cup and feels his sister''s hand and his dog''s fur.', 'in_a_trial', '["accessibility", "other"]', 'keith-thomas-double-neural-bypass', 'accessibility', 'other', 22, 'The AI works out what Keith is trying to do from his brain signals and passes it round his injured spine, and that has given one man back the use and feeling of his hand.', '["One participant only", "The figures (arm strength up 86% and 62%) come from the institute''s press release; the journal paper itself was not opened", "It needed a 15-hour brain operation and he is not fully independent", "Do not call it a cure for paralysis"]', '["https://www.biospace.com/press-releases/feinstein-institutes-technology-that-restores-movement-and-sensation-after-paralysis-featured-in-nature-medicine", "https://popsci.com/science/brain-computer-implant-paralysis-update", "https://time.com/6298543/paralysis-reversal-keith-thomas"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.kunc.org/npr-news/2024-07-25/a-neurological-disease-stole-rep-jennifer-wextons-voice-ai-helped-her-get-it-back', 'A US congresswoman who lost her voice to illness spoke in Congress in her own voice, rebuilt by AI', 'Jennifer Wexton, a member of the US House of Representatives from Virginia, has progressive supranuclear palsy, a rare brain disease that took away her speech. Her office sent more than an hour of her old speeches to the company ElevenLabs, which built an AI copy of her voice within a few days. On 25 July 2024 she used it to address the House, which NPR reported was the first time an AI-cloned voice had been used on the House floor.', 'helping_people_now', '["accessibility", "voice"]', 'jennifer-wexton-ai-voice-in-congress', 'accessibility', 'voice', 22, 'The AI rebuilt her own voice from old recordings, so she kept doing her job and sounded like herself instead of a robotic text reader.', '["The voice is a recreation from old recordings and she types what it says", "The illness itself is not treated", "NPR says it was a first for the House floor, not for any parliament anywhere", "Similar in kind to other voice-clone stories already in the bank, so space them apart"]', '["https://www.kunc.org/npr-news/2024-07-25/a-neurological-disease-stole-rep-jennifer-wextons-voice-ai-helped-her-get-it-back"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://blog.google/technology/ai/google-ai-global-flood-forecasting/', 'AI river flood forecasts running in more than 80 countries', 'Google researchers showed in Nature that an AI model forecasts extreme river floods five days ahead as reliably as the leading global system manages on the day itself, including on rivers with no measuring gauges. The model runs in a free public warning system covering more than 80 countries. Google says the forecasts reach up to seven days ahead and cover 460 million people.', 'helping_people_now', '["climate_and_nature", "forecasting"]', 'flood-forecasts-80-countries', 'climate_and_nature', 'forecasting', 21, 'The AI gives days of warning for free, including on rivers with no measuring gauges, in more than 80 countries.', '["The seven days and 460 million people are Google''s own figures. The Nature paper showed five days."]', '["https://blog.google/technology/ai/google-ai-global-flood-forecasting/", "https://doi.org/10.1038/s41586-024-07145-1"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://news.cornell.edu/node/321931', 'Merlin tells you which bird is singing', 'In June 2021 the Cornell Lab of Ornithology added Sound ID to its free Merlin Bird ID app. The phone listens and shows a live list, with photos, of the birds singing nearby, even when several sing at once. It works by turning sound into pictures and using image-recognition AI trained on thousands of recordings shared by birdwatchers, and it launched with more than 400 species from the US and Canada.', 'helping_people_now', '["everyday_life", "other"]', 'merlin-birdsong-id', 'everyday_life', 'other', 21, 'Anyone with a phone can find out which birds are singing around them, thanks to AI trained on recordings shared by birdwatchers.', '[]', '["https://news.cornell.edu/node/321931"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://abc17news.com/news/national-world/cnn-world/2023/12/14/in-india-ai-enabled-cameras-are-sending-out-tiger-alerts-in-real-time/', 'AI cameras in central India send a tiger alert to rangers'' phones in about 30 seconds', 'Researchers put 12 small AI cameras in the forest corridor between the Kanha and Pench tiger reserves in Madhya Pradesh, India, for a two month trial. The cameras recognise tigers and people on the spot and send the picture to rangers'' phones about 30 seconds after the animal walks past. Rangers pass sightings near villages on to residents by WhatsApp or Telegram, and a second trial in Dudhwa tiger reserve led to four poachers being arrested.', 'in_a_trial', '["climate_and_nature", "vision"]', 'tiger-alert-cameras-kanha-pench', 'climate_and_nature', 'vision', 21, 'The AI inside the camera sorts tigers and poachers from everything else and sends only those pictures, so villagers get a warning while the tiger is still nearby and rangers do not wade through thousands of empty photos.', '["This was a two month trial with 12 cameras, not a permanent system.", "The study shows the alerts work. It does not show that attacks on people or livestock went down.", "The four arrests in Dudhwa and the 98.8% accuracy figure are as reported by CNN; I did not see them in the paper''s summary.", "The camera was built by the US non-profit Resolve, whose staff are among the paper''s authors."]', '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=PMCID:PMC10580963&resultType=core&format=json", "https://abc17news.com/news/national-world/cnn-world/2023/12/14/in-india-ai-enabled-cameras-are-sending-out-tiger-alerts-in-real-time/"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.aljazeera.com/program/newsfeed/2020/11/23/blind-runner-completes-solo-5k-guided-by-ai/', 'A blind runner completed a 5 km run alone in Central Park, guided by AI on his phone', 'Thomas Panek, who is blind and leads the charity Guiding Eyes for the Blind, ran 5 km on his own in New York''s Central Park in November 2020. A phone on his waistband used AI to spot a line marked on the path, and sounds in his headphones told him when he drifted left or right. He had needed guide dogs or human guides to run before that.', 'in_a_trial', '["accessibility", "vision"]', 'blind-runner-solo-5k-central-park', 'accessibility', 'vision', 21, 'The AI in the phone did the job of a guide by watching the line and steering him with sound, which gave a blind runner the freedom to run alone.', '["It was a Google research project, not an app the public can download", "It only works where a line has been marked on the ground", "One runner on one prepared course"]', '["https://www.aljazeera.com/program/newsfeed/2020/11/23/blind-runner-completes-solo-5k-guided-by-ai/", "https://blog.google/outreach-initiatives/accessibility/project-guideline/"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.povertyactionlab.org/project/using-mobile-phone-and-satellite-data-target-togos-emergency-cash-transfer-program', 'Togo used AI and phone data to get emergency cash to its poorest people during Covid', 'When Covid hit in 2020, Togo launched Novissi, a programme that sent emergency cash to people''s mobile phones, but the country had no up-to-date list of who was poorest. Researchers used AI on satellite pictures to find the poorest areas and on phone use records to find the poorest people in them. A study in Nature in 2022 found this left 4 to 21% fewer needy people wrongly missed out than the area-based methods the government was considering.', 'helping_people_now', '["everyday_life", "other"]', 'togo-novissi-ai-cash-aid', 'everyday_life', 'other', 21, 'The AI found people in need without a household survey that Togo did not have time for, so more of the money reached the poorest.', '["The 4 to 21% is against the simpler area-based options, not against an ideal system", "A full, up-to-date social register would have done better than the AI, by 9 to 35%, had one existed", "Do not attribute the whole programme''s reach of over half a million people to the AI part", "Researchers say it should not replace traditional methods when there is time and data"]', '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:10.1038/s41586-022-04484-9&resultType=core&format=json", "https://www.povertyactionlab.org/project/using-mobile-phone-and-satellite-data-target-togos-emergency-cash-transfer-program"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.rijksmuseum.nl/en/press/press-releases/for-the-first-time-in-300-years-the-night-watch-is-complete-again', 'AI repaints the edges of Rembrandt''s Night Watch that were cut off 300 years ago', 'In 1715 Rembrandt''s Night Watch was trimmed on all four sides to fit a wall in Amsterdam''s City Hall, and the strips were never found. In June 2021 the Rijksmuseum in Amsterdam showed the painting complete for the first time in 300 years. Its scientists had taught an AI Rembrandt''s technique and colours, then had it recreate the missing parts from a small copy made in the 17th century. The new pieces were printed and hung around the original.', 'in_a_trial', '["science", "vision"]', 'night-watch-missing-edges', 'science', 'vision', 21, 'The AI turned another painter''s small copy into Rembrandt''s own style at full size, so visitors saw the picture as he composed it, including 64 centimetres on the left that had been lost.', '["The added pieces are printed reconstructions placed around the painting, not recovered Rembrandt paint.", "The display was temporary, for some months in 2021, and the museum said it would not add the pieces in the real restoration.", "The reconstruction rests on a 17th-century copy attributed to Gerrit Lundens."]', '["https://www.rijksmuseum.nl/en/press/press-releases/for-the-first-time-in-300-years-the-night-watch-is-complete-again"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1038/s41591-024-02961-4', 'AI heart-trace alerts cut deaths among hospital patients in a Taiwan trial', 'Doctors at Tri-Service General Hospital in Taipei ran a trial with 39 physicians and 15,965 patients. An AI read each patient''s routine heart trace and sent the doctor a warning when it judged the patient at high risk of dying. Within 90 days, 3.6% of patients whose doctors got the alerts had died, against 4.3% of those whose doctors did not. The trial was published in Nature Medicine.', 'in_a_trial', '["health", "other"]', 'taiwan-ecg-alert-fewer-deaths', 'health', 'other', 21, 'The AI picked out the patients in most danger from a routine heart trace and warned their doctors. Fewer of those doctors'' patients died, in a randomised trial.', '["One hospital system in Taiwan. It has not yet been repeated elsewhere as far as we found.", "The gain was concentrated in patients the AI flagged as high risk.", "The authors say exactly how the alerts led to fewer deaths still needs explaining.", "Say 3.6% against 4.3%, not ''slashed'' or ''halved''."]', '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:10.1038/s41591-024-02961-4&resultType=core&format=json"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=AUTH:%22Stringer%20JSA%22%20AND%20TITLE:%22gestational%20age%22%20AND%20JOURNAL:%22JAMA%22%20AND%20PUB_YEAR:2024&resultType=core&format=json', 'With an AI handheld scanner, beginners date pregnancies as well as trained sonographers', 'Researchers from the University of North Carolina and the University of Zambia tested a handheld ultrasound probe with built-in AI on 400 pregnant people in Lusaka, Zambia, and Chapel Hill in the United States. People with no training in ultrasound swept the probe across the belly and the AI estimated how far along the pregnancy was. Their estimates were off by 3.2 days on average, against 3.0 days for trained sonographers. The study was published in JAMA.', 'in_a_trial', '["health", "vision"]', 'pregnancy-ultrasound-novices-zambia', 'health', 'vision', 21, 'The AI did the skilled part of the scan, so someone with no ultrasound training got an answer within a fraction of a day of a trained sonographer''s.', '["This was a study at two sites, not routine use.", "The main test covered scans between 14 and 27 weeks of pregnancy.", "It estimates how far along a pregnancy is. It does not check the baby''s health.", "The pregnancies studied were single babies with no known problems."]', '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=AUTH:%22Stringer%20JSA%22%20AND%20TITLE:%22gestational%20age%22%20AND%20JOURNAL:%22JAMA%22%20AND%20PUB_YEAR:2024&resultType=core&format=json"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.jpl.nasa.gov/news/nasas-perseverance-rover-completes-first-ai-planned-drive-on-mars/', 'Perseverance completes the first AI-planned drives on Mars', 'On 8 and 10 December 2025, NASA''s Perseverance rover drove 210 metres and then 246 metres along the rim of Jezero Crater on routes planned by generative AI instead of human route planners. NASA called them the first drives on another world planned by AI. Engineers checked the commands on a virtual copy of the rover before sending them to Mars.', 'in_a_trial', '["space", "language model"]', 'perseverance-ai-planned-drive', 'space', 'language model', 20, 'AI planned the rover''s route instead of human route planners, and the rover drove it, a first on another world.', '["A demonstration of two drives. Engineers checked the commands on a virtual copy of the rover first."]', '["https://www.jpl.nasa.gov/news/nasas-perseverance-rover-completes-first-ai-planned-drive-on-mars/"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1038/s41586-023-06443-4', 'AI turns brain signals into speech and a talking avatar', 'In a clinical trial reported in Nature, researchers recorded brain signals from a participant with severe paralysis who was unable to speak, as the person tried to say sentences silently. Deep learning models turned the signals into text at a median of 78 words a minute, into speech personalised to the participant''s voice from before the injury, and into the facial movements of an on-screen avatar.', 'in_a_trial', '["accessibility", "voice"]', 'speech-avatar-after-paralysis', 'accessibility', 'voice', 20, 'AI turned brain signals into text at 78 words a minute, into a voice like the person''s own, and into a face that moves as they speak.', '["One participant in a clinical trial. Their name and gender were not confirmed, so say ''someone''."]', '["https://doi.org/10.1038/s41586-023-06443-4"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1073/pnas.2407652121', 'AI helps find 303 new Nazca figures in six months', 'It took nearly a century to find 430 of the ancient figures drawn into the ground at Nazca in Peru. A team led by Yamagata University used AI to search the whole region and found 303 more in six months of fieldwork, nearly doubling the known total. The results were published in PNAS in September 2024.', 'in_the_lab', '["science", "vision"]', 'nazca-303-new-figures', 'science', 'vision', 20, 'The AI searched the whole region and helped find, in six months, nearly as many figures as people had found in a century.', '[]', '["https://doi.org/10.1073/pnas.2407652121"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://scrollprize.org/grandprize', 'Students use AI to read a scroll charred by Vesuvius', 'Three students, Youssef Nader, Luke Farritor and Julian Schilliger, won the $700,000 Vesuvius Challenge grand prize in February 2024 for reading a rolled-up scroll from Herculaneum that was charred when Vesuvius erupted about 2,000 years ago. Machine learning picked out ink in X-ray scans, revealing more than 2,000 characters across 15 columns of Greek. The text is a previously unknown work of philosophy about pleasure, touching on music and food, and a team of papyrologists reviewed the result.', 'in_the_lab', '["science", "vision"]', 'herculaneum-scroll-read', 'science', 'vision', 20, 'The scroll is charred and rolled shut. Machine learning picked out the ink in X-ray scans, so a lost work of philosophy can be read again.', '[]', '["https://scrollprize.org/grandprize", "https://www.scientificamerican.com/article/ai-unravels-ancient-roman-scrolls-charred-by-volcano/"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.raeng.org.uk/news/kenyan-innovator-elly-savatia-named-the-2025-africa-prize-for-engineering-innovation', 'A Kenyan app turns speech into sign language with lifelike 3D avatars', 'Elly Savatia of Kenya built Terp 360, an AI app that turns speech into sign language shown by 3D avatars. His team worked with Kenya''s deaf community to record more than 2,300 signs. In October 2025 it won the Royal Academy of Engineering''s Africa Prize for Engineering Innovation, worth £50,000, and Kenya''s Star newspaper reports that it has reached more than 2,000 deaf users.', 'helping_people_now', '["accessibility", "language model"]', 'terp-360-kenyan-sign-language-avatars', 'accessibility', 'language model', 20, 'The AI does the interpreting where there are too few human sign language interpreters, which helps deaf people follow what is said in classrooms and public services.', '["The figure of more than 2,000 users comes from the company''s side and was reported by The Star, not by the Royal Academy", "It translates speech into sign language, not sign language into speech", "No independent test of how accurate the signing is"]', '["https://www.raeng.org.uk/news/kenyan-innovator-elly-savatia-named-the-2025-africa-prize-for-engineering-innovation", "https://www.the-star.co.ke/health/2025-10-23-kenyan-creates-first-sign-language-app"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.rnz.co.nz/news/top/531303/why-google-maps-can-t-pronounce-maori-place-names', 'A Māori radio station built its own AI that understands the Māori language, using voices from its community', 'Te Hiku Media, a Māori broadcaster in the Far North of New Zealand, built AI tools that write down spoken te reo Māori, give feedback on pronunciation and turn text into speech. More than 2,500 people signed up in ten days to read phrases aloud, which gave over 300 hours of recordings, and the data is held under a licence that keeps its use for the benefit of Māori. The tools run a transcription service and help about 20 Māori radio stations search more than 30 years of archive recordings.', 'helping_people_now', '["everyday_life", "voice"]', 'te-hiku-maori-speech-ai', 'everyday_life', 'voice', 20, 'The AI makes decades of recordings in an endangered language searchable and helps learners with pronunciation, and the community that speaks the language owns it.', '["The 92% accuracy figure is Te Hiku''s own claim and has not been independently tested, so leave it out or attribute it", "Most detail on the data comes from a blog by Nvidia, whose tools Te Hiku used", "No confirmed date for the recording campaign"]', '["https://www.rnz.co.nz/news/top/531303/why-google-maps-can-t-pronounce-maori-place-names", "https://blogs.nvidia.com/blog/te-hiku-media-maori-speech-ai/"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1038/s41591-022-01894-0', 'Sepsis early-warning AI linked to fewer deaths at five hospitals', 'An AI early-warning system for sepsis called TREWS monitored 590,736 patients across five hospitals in a study led by Johns Hopkins. Among 6,877 sepsis patients the system flagged before antibiotics were started, those whose alert was confirmed by a clinician within three hours had a lower death rate, a relative reduction of 18.7%. The study was published in Nature Medicine in July 2022.', 'helping_people_now', '["health", "other"]', 'sepsis-early-warning-johns-hopkins', 'health', 'other', 19, 'The AI flags sepsis before treatment has started, and when a clinician acted on the alert within three hours, fewer patients died.', '["An association, not a randomised result. The 18.7% compares alerts confirmed within three hours with those that weren''t."]', '["https://doi.org/10.1038/s41591-022-01894-0"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://iopscience.iop.org/article/10.3847/2041-8213/ac66d4', 'A drone and AI find a freshly fallen meteorite in the Australian outback', 'After cameras recorded a fireball over Western Australia on 1 April 2021, a Curtin University team led by PhD student Seamus Anderson worked out roughly where the rock had landed on the Nullarbor Plain. They flew a drone over about five square kilometres at Kybo Station, and an AI trained on photos of earlier meteorites flagged likely rocks in the pictures. On the fourth day they picked up a 70 gram meteorite within 50 metres of the predicted line, which the team says is the first found this way.', 'in_a_trial', '["space", "vision"]', 'drone-and-ai-find-meteorite-nullarbor', 'space', 'vision', 19, 'Meteorite hunts usually mean lines of people walking the ground for days, and the team says the drone and AI search needs about a tenth of the labour and time.', '["People still checked the AI''s picks and threw out false alarms before walking to the rock.", "''First'' is the authors'' own claim, made in their paper in The Astrophysical Journal Letters.", "The ''one tenth of the labour and time'' figure is the team''s estimate in Curtin''s release, not a measured comparison.", "This was one successful search, not yet a routine method."]', '["https://iopscience.iop.org/article/10.3847/2041-8213/ac66d4", "https://arxiv.org/abs/2203.01466", "https://www.curtin.edu.au/news/media-release/drones-and-artificial-intelligence-aid-hunt-for-fallen-meteorite-in-outback-wa/"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://blog.google/outreach-initiatives/accessibility/making-audio-more-accessible-two-new-apps/', 'A deaf scientist helped build a free phone app that captions conversations as they happen', 'Dimitri Kanevsky, a Google research scientist who has been deaf since early childhood, worked with engineer Chet Gnegy on Live Transcribe, an Android app that turns speech around the phone into written captions in real time. Staff at Gallaudet University, a university for deaf and hard-of-hearing students, helped design and test it. Google released it in February 2019 with support for more than 70 languages and dialects.', 'helping_people_now', '["accessibility", "voice"]', 'live-transcribe-captions-for-deaf-people', 'accessibility', 'voice', 19, 'AI speech recognition writes out what people are saying as they say it, so a deaf person follows a chat at a counter or a meeting with only a phone.', '["It is a Google product and the description comes largely from Google; Hearing Tracker''s report is the independent source", "Captions contain mistakes, and at launch the app relied on cloud-based speech recognition", "It launched as a limited beta on Android only", "No usage numbers were confirmed"]', '["https://blog.google/outreach-initiatives/accessibility/making-audio-more-accessible-two-new-apps/", "https://www.hearingtracker.com/news/google-live-transcribe-app"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1016/S0140-6736(25)02464-X', 'AI-supported breast screening in Sweden finds more cancers with less reading', 'The MASAI trial in Sweden randomly assigned more than 105,000 women to breast screening read with AI support or to standard double reading by two radiologists. The AI-supported group had higher sensitivity (80.5% against 73.8%), the same specificity, and no more cancers turning up between screenings. An earlier analysis from the same trial found the screen-reading workload fell by 44.3%.', 'in_a_trial', '["health", "vision"]', 'masai-breast-screening-sweden', 'health', 'vision', 18, 'One radiologist working with AI found more cancers than two radiologists working together, with no extra false alarms, and the reading workload fell by 44%.', '["Don''t say fewer cancers were missed between screenings: that difference was not statistically significant."]', '["https://doi.org/10.1016/S0140-6736(25)02464-X", "https://doi.org/10.1016/S1470-2045(23)00298-X"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1038/s41746-018-0040-6', 'First AI cleared to check for diabetic eye disease without a specialist', 'A trial in primary care clinics tested an AI system that checks photos of the back of the eye for diabetic retinopathy in 900 people with diabetes. It beat all its pre-set targets, and the US regulator then authorised it as the first autonomous AI diagnostic system in any field of medicine. It gives a result without an eye specialist needing to look at the image.', 'helping_people_now', '["health", "vision"]', 'diabetic-eye-check-without-specialist', 'health', 'vision', 18, 'People with diabetes can have their eyes checked for damage at an ordinary clinic, with the AI giving the result and no eye specialist needed.', '["Authorised in the US in 2018. How widely it is used today was not confirmed."]', '["https://doi.org/10.1038/s41746-018-0040-6", "https://www.hcinnovationgroup.com/clinical-it/article/13009587/fda-permits-marketing-of-artificial-intelligence-based-device-to-detect-certain-diabetes-related-eye-problems"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1038/s41559-024-02420-w', 'AI helps show that elephants call each other by name', 'Researchers used machine learning on the calls of wild African elephants and showed that the elephant a call was meant for can be predicted from the sound of the call itself. When calls were played back, elephants responded more to calls originally addressed to them than to calls meant for another elephant. The study was published in Nature Ecology and Evolution in June 2024.', 'in_the_lab', '["science", "other"]', 'elephants-name-each-other', 'science', 'other', 18, 'Machine learning could tell which elephant a call was meant for from the sound alone, which is how the name-like calls were found.', '["Say ''something like names''. It is a discovery about animals, and nobody is using it for anything yet."]', '["https://doi.org/10.1038/s41559-024-02420-w"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.ecmwf.int/en/about/media-centre/news/2025/ecmwfs-ai-forecasts-become-operational', 'Europe''s weather centre switches on an AI forecast', 'On 25 February 2025 the European Centre for Medium-Range Weather Forecasts made its AI forecasting system, the AIFS, fully operational, running alongside its traditional physics-based model. The centre says it outperforms state-of-the-art physics-based models on many measures, including the tracks of tropical cyclones, with gains of up to 20%. It uses roughly 1,000 times less energy to produce a forecast.', 'helping_people_now', '["everyday_life", "forecasting"]', 'ecmwf-ai-weather-forecast', 'everyday_life', 'forecasting', 18, 'An AI forecast now runs every day at Europe''s weather centre, beating the traditional method on many measures for about a thousandth of the energy.', '["The performance figures are the centre''s own.", "It runs alongside the traditional model, not instead of it."]', '["https://www.ecmwf.int/en/about/media-centre/news/2025/ecmwfs-ai-forecasts-become-operational"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1038/s41598-025-97652-6', 'Students learn more in less time with an AI tutor in a Harvard trial', 'In a randomised controlled trial in a Harvard physics course, students learnt material either through a specially designed AI tutor or in an active-learning class built on the same teaching principles. Those using the AI tutor learnt significantly more in less time, and felt more engaged and motivated. The trial was published in Scientific Reports in June 2025; it covered one course and tested learning in the short term.', 'in_a_trial', '["everyday_life", "language model"]', 'harvard-ai-tutor-trial', 'everyday_life', 'language model', 18, 'Students with the AI tutor learnt more in less time, and felt more engaged, than students in an already well-taught class.', '["One course, short-term tests, not yet repeated elsewhere.", "The tutor was specially designed for the course. It was not a general chatbot."]', '["https://doi.org/10.1038/s41598-025-97652-6"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://wildsalmoncenter.org/2023/10/18/artificial-intelligence-meet-indigenous-fishing-technology/', 'AI counts salmon swimming past First Nations fish fences in British Columbia', 'On the Kitwanga, Bear and Koeye rivers in British Columbia, First Nations fisheries teams and the Wild Salmon Center put underwater video cameras at traditional fish-counting fences and trained an AI called Salmon Vision to recognise and count the fish going past. In a pilot published in Frontiers in Marine Science, it was more than 90% accurate for coho salmon and more than 80% for sockeye, and it tracks 12 kinds of fish.', 'in_a_trial', '["climate_and_nature", "vision"]', 'salmon-vision-first-nations-weirs', 'climate_and_nature', 'vision', 18, 'Salmon numbers are usually not known until the season is over, and the AI counts the fish as they pass, so the Nations who look after these rivers get the numbers while there is still time to act on them.', '["This is a pilot on a few rivers. Real-time counts for partners were a goal for 2024, not something the source says has happened.", "Accuracy differs by species: over 90% for coho, over 80% for sockeye.", "I confirmed the details on the Wild Salmon Center''s own page, which is one of the project partners. I did not open the journal paper itself.", "The partners named are the Gitanyow Fisheries Authority, Skeena Fisheries Commission, Heiltsuk Nation and Pacific Salmon Foundation. Do not credit the AI alone."]', '["https://wildsalmoncenter.org/2023/10/18/artificial-intelligence-meet-indigenous-fishing-technology/"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://news.northwestern.edu/stories/2023/10/first-supernova-detected-confirmed-classified-and-shared-by-ai/', 'An AI finds, confirms and announces an exploding star with no human involved', 'In October 2023 an AI tool called BTSbot, built by a team led from Northwestern University, picked out a possible exploding star in pictures from a robotic telescope at Palomar Observatory in California. It asked a second robotic telescope for a closer look, the result was classified automatically as a supernova, and the discovery was shared with astronomers worldwide two days later. Northwestern says it was the first time the whole process happened without a person. The method has since been published in The Astrophysical Journal.', 'helping_people_now', '["space", "vision"]', 'btsbot-first-fully-automatic-supernova', 'space', 'vision', 18, 'People on the team had spent about 2,200 hours over six years checking candidates by eye, and the AI now does that sorting so astronomers have more time to study the explosions.', '["The supernova itself, SN2023tyk, is an ordinary one. The news is that no human was needed, not the star.", "''First ever'' is the team''s own claim, repeated in their journal paper.", "BTSbot does the spotting. A separate automatic tool, SNIascore, did the classifying.", "Search results suggested human scanners also saw the same object. Do not say the AI found something people missed.", "The 2,200 hours figure is Northwestern''s estimate."]', '["https://news.northwestern.edu/stories/2023/10/first-supernova-detected-confirmed-classified-and-shared-by-ai/", "https://par.nsf.gov/biblio/10578341"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://dandc.eu/en/article/malawi-tool-blind%20students', 'A talking AI classroom helps blind pupils in Malawi study on their own', 'Staff Nyoni, a young Malawian who studied ICT, built Blind Classroom, an AI learning system that reads lessons aloud, asks questions and lets pupils answer by voice. It is being piloted at Chilanga School for the Blind and St Joseph Resource Centre in central Malawi, with backing from Save the Children. Yankho Maganga, 14, who used to rely on Braille and a teacher''s help, says she is now among the top performers in her class.', 'in_a_trial', '["accessibility", "voice"]', 'blind-classroom-malawi', 'accessibility', 'voice', 18, 'The AI turns written lessons into spoken ones a blind pupil can replay and answer by voice, so children at the two pilot schools can study without waiting for a teacher or Braille copies.', '["It is a pilot in two schools; the move to 14 schools is planned, not finished", "Yankho''s improved grades are her own account, not a measured study result", "Not all subjects are loaded into the system yet", "The article does not say which AI models it uses"]', '["https://dandc.eu/en/article/malawi-tool-blind%20students"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.miraikan.jst.go.jp/en/lab/AIsuitcase/', 'A suitcase that steers itself guides blind visitors round a museum in Japan', 'Chieko Asakawa, a blind IBM Fellow who leads the Miraikan science museum in Japan, came up with the AI Suitcase on a business trip. It looks like ordinary luggage, but it uses sensors and image-recognition AI to spot walls, obstacles and people, and it leads its user to a chosen place while the handle vibrates to signal turns. A regular pilot service began at Miraikan in April 2024, with daily tours, and a large field trial ran at Expo 2025 in Osaka.', 'in_a_trial', '["accessibility", "vision"]', 'ai-suitcase-guides-blind-visitors-japan', 'accessibility', 'vision', 18, 'The AI recognises people and obstacles and plans a safe route, so a blind person can walk through a busy building without a human guide.', '["It is a pilot service and field trials, not a product on sale", "Miraikan gives no figures for how many people have used it and no results from the Expo trial", "Tours follow set routes inside the museum"]', '["https://www.miraikan.jst.go.jp/en/lab/AIsuitcase/"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://pmc.ncbi.nlm.nih.gov/articles/PMC7775399', 'A free phone app spots cassava disease better than farmers and farm advisers in East Africa', 'PlantVillage Nuru is a free phone app that uses AI to look at a cassava leaf through the camera and say whether the plant has a disease, with advice on what to do. Researchers tested it in Tanzania and western Kenya and published the results in Frontiers in Plant Science in December 2020. The app was right 65% of the time, compared with 40 to 58% for agricultural advisers and 18 to 31% for farmers, and it works without a phone signal.', 'in_a_trial', '["everyday_life", "vision"]', 'plantvillage-nuru-cassava-disease-app', 'everyday_life', 'vision', 18, 'The AI puts an expert eye in a farmer''s pocket, even where there is no signal, for a crop that many families depend on.', '["65% is well short of trained experts, who scored 81 to 95% in the same study", "It was weak on one disease, cassava brown streak, from a single leaf; checking six leaves gave 74 to 88%", "The study measured diagnosis, not whether harvests improved"]', '["https://pmc.ncbi.nlm.nih.gov/articles/PMC7775399"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.who.int/news/item/11-06-2025-who-approves-six-software-products-for-computer-aided-detection-of-tb-on-chest-x-ray', 'AI that reads chest X-rays for tuberculosis is now backed by the World Health Organization', 'Since 2021 the World Health Organization has recommended software that reads chest X-rays to screen people aged 15 and over for tuberculosis, and in June 2025 it said six products met its standards. In a study of 23,954 people at three screening centres in Dhaka, Bangladesh, five AI programs were compared with three radiologists, and all five did significantly better. Anyone the software flags still gets a confirming test before treatment.', 'helping_people_now', '["health", "vision"]', 'tb-xray-ai-who', 'health', 'vision', 18, 'WHO calls screening with chest X-rays and this software essential for finding tuberculosis cases that are being missed. In the Dhaka study the AI halved the number of confirming tests needed while still catching more than 90% of cases.', '["The AI screens. It does not diagnose: a positive result needs a confirming test.", "WHO does not recommend it for children under 15.", "The Dhaka study tested the programs on X-rays taken between 2014 and 2016, not in live use.", "The WHO page does not name the countries using it, so do not name any."]', '["https://www.who.int/news/item/11-06-2025-who-approves-six-software-products-for-computer-aided-detection-of-tb-on-chest-x-ray", "https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22Tuberculosis%20detection%20from%20chest%20x-rays%20for%20triaging%20in%20a%20high%20tuberculosis-burden%20setting%22&resultType=core&format=json"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1038/s44172-024-00329-7', 'Pilots cut planet-warming vapour trails using AI forecasts', 'In a randomised trial on commercial American Airlines flights, pilots changed altitude to avoid air where forecasts, including one from a machine learning model, said vapour trails would form. Satellite images showed 64% fewer trails on those flights than on comparison flights, for about 2% more fuel on the adjusted flights. The study, by Google Research, American Airlines and Breakthrough Energy, was published in Communications Engineering in December 2024.', 'in_a_trial', '["climate_and_nature", "forecasting"]', 'contrail-avoidance-flights', 'climate_and_nature', 'forecasting', 17, 'AI forecasts told pilots where vapour trails would form, and a small change of height avoided 64% of them.', '["A trial, led by Google Research with American Airlines.", "It cost about 2% more fuel on the adjusted flights."]', '["https://doi.org/10.1038/s44172-024-00329-7"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1038/s41586-020-2824-5', 'AI counts 1.8 billion trees across the West African Sahara and Sahel', 'Scientists used deep learning on very sharp satellite images to map the crown of every tree across about 1.3 million square kilometres of the West African Sahara, Sahel and neighbouring sub-humid zone. They found more than 1.8 billion individual trees, an unexpectedly large number that challenges the usual story of dryland turning to desert. The study was published in Nature in October 2020.', 'in_the_lab', '["climate_and_nature", "vision"]', 'sahara-sahel-tree-count', 'climate_and_nature', 'vision', 17, 'The AI mapped every single tree across 1.3 million square kilometres, a count nobody could do by hand, and found far more than expected.', '["A finding about what is there, not a change on the ground."]', '["https://doi.org/10.1038/s41586-020-2824-5"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22Dating%20ancient%20manuscripts%20using%20radiocarbon%20and%20AI-based%20writing%20style%20analysis%22&resultType=core&format=json', 'AI that studies handwriting suggests many Dead Sea Scrolls are older than thought', 'A team led from the University of Groningen in the Netherlands trained an AI called Enoch on the handwriting of 24 Dead Sea Scroll samples whose age had been measured by radiocarbon dating. They then used it to estimate the age of 135 scrolls that had never been dated. Many came out older than scholars had estimated from the handwriting by eye, and the study was published in PLOS One.', 'in_the_lab', '["science", "vision"]', 'dead-sea-scrolls-ai-dating', 'science', 'vision', 17, 'Only 24 samples had a measured radiocarbon age to learn from. The AI used them to give an age estimate for 135 more scrolls from their handwriting alone.', '["The model learned from only 24 dated samples and its typical error is about 28 to 31 years.", "Handwriting experts judged about 79% of its estimates realistic, not all of them.", "Press coverage reported that some scroll scholars are not convinced by the earlier dates, so say ''suggests'', not ''proves''.", "Do not say the Bible has been re-dated."]', '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22Dating%20ancient%20manuscripts%20using%20radiocarbon%20and%20AI-based%20writing%20style%20analysis%22&resultType=core&format=json"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.nottingham.ac.uk/news/madonna-della-rosa', 'AI finds that one face in a Raphael painting was probably painted by someone else', 'Researchers from the universities of Bradford, Nottingham and Stanford trained an AI on authenticated paintings by Raphael and pointed it at the Madonna della Rosa, which hangs in the Prado in Madrid. Tested as a whole, the painting gave no clear answer. Tested piece by piece, most of it came out as Raphael''s work, but the face of Joseph most likely did not. The study was published in the journal Heritage Science.', 'in_the_lab', '["science", "vision"]', 'raphael-joseph-face', 'science', 'vision', 17, 'The AI gave art experts a new kind of evidence about who painted what, and it pointed to one specific face in a famous picture.', '["The researchers say the result is not enough on its own to decide who painted what. It is one tool to help experts.", "The 98% accuracy figure is the team''s own test result for the model.", "Giulio Romano is only suggested as a possible painter of Joseph''s face.", "Some art historians were dismissive of the work in press coverage, and the Prado has not changed its attribution as far as we found.", "The journal page could not be opened directly: facts were confirmed on the University of Nottingham''s own news page."]', '["https://www.nottingham.ac.uk/news/madonna-della-rosa"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://bibliotecahistorica.blogs.uva.es/2023/02/23/el-nuevo-hallazgo-de-lope-de-vega/', 'AI spots an unknown play by Lope de Vega among anonymous manuscripts in Spain''s National Library', 'Researchers from the universities of Valladolid and Vienna used AI to transcribe about 1,300 plays from Spain''s Golden Age, then compared the wording of each with known authors. One anonymous manuscript in the National Library of Spain, La francesa Laura, matched Lope de Vega, one of Spain''s greatest playwrights. The researchers then checked it by traditional methods, including its verse, and the library announced the find in early 2023.', 'in_the_lab', '["science", "other"]', 'lope-de-vega-lost-play', 'science', 'other', 17, 'The play had sat in the library''s catalogue since 1882 with no author. AI read the handwriting in hours and picked it out from the pile, which let scholars focus their checking on the right manuscript.', '["The attribution rests on writing style, checked by scholars. No document names Lope as the author.", "Say ''attributed to'', and that the play dates from the last years before his death in 1635.", "The National Library''s own announcement could not be opened: facts were confirmed on University of Valladolid and University of Innsbruck pages and in news reports."]', '["https://bibliotecahistorica.blogs.uva.es/2023/02/23/el-nuevo-hallazgo-de-lope-de-vega/", "https://www.uibk.ac.at/de/newsroom/2023/ki-entdeckt-bisher-unbekannte-komodie/", "https://www.eldebate.com/cultura/20230131/inteligencia-artificial-descubre-autor-obra-anonima-fondos-biblioteca-nacional-lope-vega_90151_amp.html", "https://www.thestar.com.my/lifestyle/culture/2023/02/02/ai-uncovers-unknown-play-by-spanish-great-in-library-archive"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.ed.ac.uk/news/ai-sheds-light-on-mysterious-dinosaur-footprints', 'AI trained on 2,000 fossil footprints helps work out which dinosaur made them', 'Researchers led by the Helmholtz-Zentrum Berlin, working with the University of Edinburgh, trained an AI on nearly 2,000 fossil footprints. It agreed with human experts about 90% of the time on what kind of dinosaur made a track, including ones experts argue over. It also found that some tracks more than 200 million years old share features with the feet of birds. The study was published in PNAS, and an app called DinoTracker lets anyone upload a photo or sketch of a footprint for analysis.', 'in_the_lab', '["science", "vision"]', 'dinosaur-footprint-ai', 'science', 'vision', 17, 'Fossil footprints are common but hard to read, and experts often disagree. The AI gives a consistent second opinion and puts a tool once limited to specialists in the hands of anyone who finds a track.', '["The bird-like tracks have two explanations in the source: birds began much earlier than thought, or some early dinosaurs simply had bird-like feet. Do not pick one.", "''About 90%'' is agreement with experts, who can themselves be wrong.", "The source does not say whether the app is free."]', '["https://www.ed.ac.uk/news/ai-sheds-light-on-mysterious-dinosaur-footprints"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22Automated%20detection%20of%20koalas%20using%20low-level%20aerial%20surveillance%20and%20machine%20learning%22&resultType=core&format=json', 'Drones and AI find koalas hidden in the treetops in Queensland', 'Researchers at Queensland University of Technology flew drones with heat-sensing cameras over bushland at Petrie, Queensland, and used AI to pick out koalas by their body heat. They checked the results against koalas wearing radio collars, whose positions were known. The AI found between 68% and 100% of the koalas, with smaller errors than people checking the same footage by eye.', 'in_the_lab', '["climate_and_nature", "vision"]', 'koala-spotting-drones-queensland', 'climate_and_nature', 'vision', 16, 'Koalas are very hard to see from the ground, and the AI picks their heat out of drone footage automatically, giving wildlife managers a more reliable and less intrusive way to count them.', '["One study site, with radio-collared koalas used as the answer key.", "The AI also raised false alarms: only 43% to 71% of the things it flagged were koalas.", "The paper says manual checking of the same footage took a similar amount of time, so do not claim it is faster.", "Later use of the method after bushfires was mentioned in news reports I did not open, so leave it out."]', '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22Automated%20detection%20of%20koalas%20using%20low-level%20aerial%20surveillance%20and%20machine%20learning%22&resultType=core&format=json"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://home.treasury.gov/news/press-releases/jy2650', 'The US Treasury used AI to recover $1 billion in cheque fraud in a year', 'The US Treasury said in October 2024 that it had started using machine learning AI to spot fraud involving government cheques faster. In the year to September 2024 that work recovered $1 billion. It was part of more than $4 billion in fraud and wrongful payments that the Treasury prevented or recovered that year, up from $652.7 million the year before.', 'helping_people_now', '["everyday_life", "other"]', 'us-treasury-ai-cheque-fraud', 'everyday_life', 'other', 16, 'The AI flagged suspect cheques quickly enough for the money to be recovered, and that is public money returned to taxpayers.', '["Only the $1 billion from cheque fraud is tied to AI; the rest of the $4 billion came from other methods", "The figures are the Treasury''s own", "The total covers fraud and improper payments, not fraud alone"]', '["https://home.treasury.gov/news/press-releases/jy2650"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.lmu.de/en/newsroom/news-overview/news/hymn-to-babylon-discovered.html', 'AI helps piece together a lost hymn in praise of Babylon', 'Enrique Jiménez of LMU Munich, working with the University of Baghdad, rediscovered a hymn in praise of the ancient city of Babylon, written around 1000 BCE and about 250 lines long. His team is digitising clay tablet fragments from around the world and uses AI to find pieces that belong to the same text. The AI turned up 30 more manuscripts of the hymn, which let the scholars fill in the missing parts. The work was published in the journal Iraq.', 'in_the_lab', '["science", "other"]', 'babylon-hymn-pieced-together', 'science', 'other', 16, 'Matching scattered fragments by hand would have taken decades, the lead researcher said. With AI the team recovered a poem describing Babylon''s buildings, the Euphrates bringing spring to the fields, and the city''s priestesses.', '["''Would have taken decades'' is the researcher''s own estimate.", "The AI matched fragments. Scholars did the reading and translation.", "Facts come from LMU''s own news page describing the peer-reviewed paper (DOI 10.1017/irq.2024.23), which was not opened directly."]', '["https://www.lmu.de/en/newsroom/news-overview/news/hymn-to-babylon-discovered.html"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22A%20generative%20AI-discovered%20TNIK%20inhibitor%20for%20idiopathic%20pulmonary%20fibrosis%22&resultType=core&format=json', 'A drug found with AI improves breathing in a lung disease trial in China', 'Rentosertib is a drug for idiopathic pulmonary fibrosis, a disease that scars the lungs. The company Insilico Medicine found it using generative AI. In a trial of 71 patients run from Peking Union Medical College Hospital with other Chinese hospitals, people on the highest dose for 12 weeks gained 98 millilitres of breathing capacity on average, while those on a dummy pill lost 20. The trial was published in Nature Medicine.', 'in_a_trial', '["health", "other"]', 'ai-designed-lung-drug-trial', 'health', 'other', 16, 'A medicine that began with an AI system has now been tested against a dummy pill in patients, and the top-dose group''s breathing improved while the dummy pill group''s got worse.', '["Small, early trial: 71 patients over 12 weeks, mainly testing safety.", "The breathing gain is in the top-dose group of 18 people and needs a larger trial to confirm.", "Most patients in every group, including the dummy pill group, reported side effects, and some stopped because of liver problems or diarrhoea.", "The drug is not approved anywhere.", "Insilico is a company: the independent source is the peer-reviewed paper with hospital investigators."]', '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22A%20generative%20AI-discovered%20TNIK%20inhibitor%20for%20idiopathic%20pulmonary%20fibrosis%22&resultType=core&format=json"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1038/s41591-018-0107-6', 'AI reads eye scans as well as specialists at Moorfields', 'Researchers from DeepMind, Moorfields Eye Hospital and University College London trained an AI on 14,884 three-dimensional eye scans from patients referred to a major eye hospital. Its recommendations on who needed referring reached or exceeded those of experts across a range of sight-threatening retinal diseases. The study was published in Nature Medicine in August 2018.', 'in_the_lab', '["health", "vision"]', 'moorfields-eye-scans', 'health', 'vision', 15, 'The AI matched expert eye doctors at deciding who needs to be referred, across a range of diseases that threaten sight.', '["A study from 2018, not routine care.", "Don''t quote an accuracy percentage: none was checked."]', '["https://doi.org/10.1038/s41591-018-0107-6"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1038/s41586-021-03819-2', 'AlphaFold works out the shapes of proteins', 'Working out a protein''s shape from its building blocks had been an open problem for more than 50 years. In 2021 the AlphaFold team published in Nature the first method to regularly predict protein shapes with atomic accuracy. It has since been used to predict the structure of virtually all 200 million known proteins, more than two million people in 190 countries have used it, and its creators shared the 2024 Nobel Prize in Chemistry.', 'helping_people_now', '["science", "protein design"]', 'alphafold-protein-shapes', 'science', 'protein design', 15, 'It cracked a problem that had been open for 50 years, and more than two million people in 190 countries now use the results in their own research.', '["''Helping people now'' here means scientists are using it. Don''t claim it has produced specific cures."]', '["https://doi.org/10.1038/s41586-021-03819-2", "https://www.uu.nl/en/news/nobel-prize-in-chemistry-2024-for-alphafold2-and-protein-design"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://schoolsweek.co.uk/using-chatgpt-can-cut-lesson-planning-by-31-eef-study', 'Teachers in England planned lessons about a third faster with ChatGPT, with no drop in quality', 'A trial in England involved 259 science teachers in 68 secondary schools. Half were given ChatGPT and a guide to using it for planning lessons for 11 to 13 year olds, and half were asked not to use AI. The ChatGPT group spent 56 minutes a week on planning instead of 82, a saving of 31%, and an independent panel of teachers saw no noticeable difference in the quality of their materials.', 'in_a_trial', '["everyday_life", "language model"]', 'chatgpt-cuts-teachers-planning-time-england', 'everyday_life', 'language model', 15, 'The AI drafted quizzes, activity ideas and tailored materials, which gave teachers back about 25 minutes a week without worse lessons.', '["It covers Year 7 and 8 science planning only", "The quality check used a limited sample of materials", "Teachers were given a guide as well as the tool", "It measured teachers'' time, not pupils'' results"]', '["https://schoolsweek.co.uk/using-chatgpt-can-cut-lesson-planning-by-31-eef-study"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22Classification%20of%20pig%20calls%20produced%20from%20birth%20to%20slaughter%22&resultType=core&format=json', 'AI learns to tell a happy pig from an unhappy one by its grunts', 'A team of European researchers, including scientists at the University of Copenhagen and ETH Zurich, recorded 7,414 calls from 411 pigs in situations from birth to slaughter. They trained an AI to tell from the sound alone whether the pig was in a good or bad situation, and it got it right 91.5% of the time. The study was published in Scientific Reports.', 'in_the_lab', '["science", "voice"]', 'pig-grunts-emotions', 'science', 'voice', 15, 'A standard statistical method managed only about 62% on the same recordings. The authors say the result shows an automated system for checking pig welfare on farms can be built.', '["Nothing is in use on farms yet. This is a study on recorded calls.", "The AI sorts calls into positive or negative situations as defined by the researchers. It does not read a pig''s mind.", "Its accuracy at naming the exact situation was lower, at 81.5%."]', '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22Classification%20of%20pig%20calls%20produced%20from%20birth%20to%20slaughter%22&resultType=core&format=json"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1038/s41591-021-01335-4', 'AI reading routine heart traces helps family doctors catch weak hearts earlier', 'Mayo Clinic ran a trial across 45 clinics and hospitals in Minnesota and Wisconsin with 22,641 adults who were having a routine heart trace. For half of the care teams, an AI read the trace and told the doctor when it saw signs of a weak heart pump. Doctors who got the AI result found more new cases, 2.1% of patients against 1.6%. The trial was published in Nature Medicine.', 'in_a_trial', '["health", "other"]', 'mayo-ecg-weak-heart-pump', 'health', 'other', 15, 'The AI found a hidden warning in a test patients were already having, so more people with a weak heart were diagnosed, with no significant rise in follow-up heart scans overall.', '["The rise is from 1.6% to 2.1% of patients: real but modest.", "The trial measured new diagnoses, not whether patients lived longer."]', '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:10.1038/s41591-021-01335-4&resultType=core&format=json"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.jpl.nasa.gov/news/ai-is-helping-scientists-discover-fresh-craters-on-mars', 'AI spots fresh craters on Mars', 'A machine learning tool built at NASA''s Jet Propulsion Laboratory found a cluster of recently formed craters in a region of Mars called Noctis Fossae, the first time AI had found previously unknown craters there. A sharper camera on NASA''s Mars Reconnaissance Orbiter confirmed the find in August 2020. A researcher needs about 40 minutes to scan one of the orbiter''s images; the tool takes about five seconds.', 'in_the_lab', '["space", "vision"]', 'mars-fresh-craters', 'space', 'vision', 14, 'The AI checks an image in about five seconds where a researcher needs 40 minutes, and it found craters nobody had spotted.', '[]', '["https://www.jpl.nasa.gov/news/ai-is-helping-scientists-discover-fresh-craters-on-mars"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.nasa.gov/missions/earth/how-nasa-is-testing-ai-to-make-earth-observing-satellites-smarter/', 'A small satellite uses AI to look ahead and skip photos that would only show cloud', 'In July 2025 NASA''s Jet Propulsion Laboratory tested AI on a briefcase-sized satellite called CogniSAT-6, built by the British company Open Cosmos. The satellite tilts to look about 500 kilometres ahead along its path, the AI on board decides whether the view is cloudy or clear, and it takes a picture of the ground only when it is clear. The whole decision takes 60 to 90 seconds with no human involved, and NASA says the cloud-dodging ability is now proven.', 'in_a_trial', '["space", "vision"]', 'satellite-ai-skips-the-clouds', 'space', 'vision', 14, 'Clouds block the view for satellites like this up to two thirds of the time, and the onboard AI saves the effort for clear shots, so scientists get far more usable pictures of Earth.', '["This was a flight test, not routine use on a science mission, which NASA says is the end goal.", "Spotting wildfires, storms and eruptions from orbit are planned next tests, not results.", "The ''up to two thirds'' cloud figure and the claim of success are NASA''s own."]', '["https://www.nasa.gov/missions/earth/how-nasa-is-testing-ai-to-make-earth-observing-satellites-smarter/"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://pmc.ncbi.nlm.nih.gov/articles/PMC7755906', 'AI finds more than 109,000 craters on the Moon that nobody had catalogued', 'Researchers led from Jilin University in China taught an AI what craters look like using about 7,900 already known ones, then ran it over maps of the Moon made by China''s Chang''e-1 and Chang''e-2 orbiters. It found 109,956 new craters, more than a dozen times the number it started from, and the team worked out the rough age of nearly 19,000 of the larger ones. The results were published in Nature Communications.', 'in_the_lab', '["space", "vision"]', 'ai-finds-109000-new-moon-craters', 'space', 'vision', 14, 'Counting craters by eye is slow and experts disagree, and the AI did it across the Moon''s middle and lower latitudes, giving scientists a much fuller record of what has hit the Moon and when.', '["The new catalogue covers the Moon''s mid and low latitudes, not the poles.", "''New'' means not in the existing catalogue the team started from. The craters are old.", "Ages were estimated only for 18,996 craters wider than 8 km."]', '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=PMCID:PMC7755906&resultType=core&format=json"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1038/s41586-022-04448-z', 'AI helps historians fill the gaps in damaged ancient Greek inscriptions', 'Researchers from DeepMind and the universities of Venice, Oxford and Athens built an AI called Ithaca that suggests the missing words in damaged ancient Greek inscriptions, and estimates where and when each one was carved. Working alone, historians restored the test texts correctly 25% of the time. Working with Ithaca, they got 72% right. The results were published in Nature.', 'in_the_lab', '["science", "language model"]', 'ithaca-greek-inscriptions', 'science', 'language model', 14, 'The AI turned a slow guessing job into a partnership, nearly tripling how often historians restored a damaged text correctly, and it places inscriptions to within 30 years of their accepted dates.', '["The figures come from tests on inscriptions where the answer was already known, not from new finds.", "Ithaca on its own scored 62% on restoring text, so say it helps historians, not that it replaces them.", "DeepMind is a company: the independent source is the peer-reviewed Nature paper with university co-authors.", "Its re-dating of some Athenian decrees touches a live debate among historians, so do not call it settled."]', '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:10.1038/s41586-022-04448-z&resultType=core&format=json"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://academic.oup.com/dsh/article/36/2/430/5880040', 'Machine learning backs the old theory that Shakespeare shared the writing of Henry VIII', 'Petr Plecháč of the Czech Academy of Sciences trained a machine learning model on the favourite words and verse rhythms of Shakespeare and of a second playwright named Fletcher. He ran it across the play Henry VIII passage by passage, ignoring scene breaks. The result strongly supported the split between the two writers that a scholar named James Spedding had proposed long before, and the study was published in Digital Scholarship in the Humanities.', 'in_the_lab', '["science", "other"]', 'henry-viii-shakespeare-fletcher', 'science', 'other', 14, 'Scholars had argued over who wrote which parts of the play using their own ear for style. The AI measured word habits and rhythm across the whole text and came to the same division independently.', '["It supports an existing theory. It did not discover the collaboration.", "The paper''s summary does not give a percentage for each writer, so do not say ''half''.", "This is statistical evidence about style, not a document proving who wrote what."]', '["https://academic.oup.com/dsh/article/36/2/430/5880040"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://actu.epfl.ch/news/epfl-and-deepmind-use-ai-to-control-plasmas-for-nu', 'AI learns to hold and shape the super-hot gas inside a Swiss fusion machine', 'Scientists at EPFL''s Swiss Plasma Center in Lausanne and DeepMind trained an AI in a simulator to control the magnets of a fusion machine called TCV. They then let it run the real machine, where it held plasma, a gas heated to hundreds of millions of degrees, in a range of shapes. It also kept two separate plasmas going in the machine at the same time. The results were published in Nature.', 'in_the_lab', '["science", "other"]', 'fusion-plasma-ai-control', 'science', 'other', 14, 'One AI system learned to work the magnets for many different plasma shapes. The paper says this reduces the design effort needed each time scientists want a new one.', '["This is a research machine that makes no electricity. Do not suggest fusion power is close.", "DeepMind is a company: the independent sources are the Nature paper and EPFL."]', '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22Magnetic%20control%20of%20tokamak%20plasmas%20through%20deep%20reinforcement%20learning%22&resultType=core&format=json", "https://actu.epfl.ch/news/epfl-and-deepmind-use-ai-to-control-plasmas-for-nu"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.ligo.caltech.edu/news/ligo20250908', 'AI steadies the mirrors of a machine that listens for colliding black holes', 'LIGO detects ripples in space from colliding black holes by measuring tiny movements of its mirrors, and unwanted shaking of those mirrors drowns out the faintest signals. Researchers from Caltech, the Gran Sasso Science Institute in Italy and Google DeepMind built an AI method that steadies the mirrors, and tested it on LIGO itself. It cut the unwanted motion 30 to 100 times better than the usual methods alone, in a study published in the journal Science.', 'in_a_trial', '["space", "other"]', 'ai-steadies-ligo-mirrors', 'space', 'other', 13, 'The AI learned a better way to hold the mirrors still than engineers had found by hand, which Caltech''s scientists say opens the door to detecting bigger black holes.', '["The authors call it a proof of concept. The test on the real detector lasted one hour.", "It is not yet in everyday use and has not yet led to any new detection.", "DeepMind is a company. The independent source is Caltech''s own LIGO page and the paper in Science.", "The test site (Livingston, Louisiana) appeared only in a search summary of DeepMind''s blog, which I did not open, so leave the site unnamed."]', '["https://www.ligo.caltech.edu/news/ligo20250908"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://slcl.illinois.edu/news/2024-10-21t201245/automatic-speech-recognition-learned-understand-people-parkinsons-disease', 'Speech recognition got much better at understanding people with Parkinson''s after they taught it themselves', 'Researchers at the University of Illinois Urbana-Champaign recruited about 250 adults whose speech is affected by Parkinson''s disease, who recorded themselves on their own phones and computers. A speech recogniser trained on 151 hours of those recordings got about 24 in every 100 words wrong on new speakers with Parkinson''s, compared with about 36 in 100 for a system trained without them. The study was published in the Journal of Speech, Language, and Hearing Research and the recordings are shared with researchers, charities and companies.', 'in_the_lab', '["accessibility", "voice"]', 'speech-recognition-learns-parkinsons-voices', 'accessibility', 'voice', 13, 'Once the AI had heard enough speech from people with Parkinson''s it made far fewer mistakes with them, which matters to people who rely on voice controls and dictation.', '["It is a study result; it does not mean everyday voice assistants already work this well", "About a quarter of words were still wrong", "The exact error rates are 23.69% and 36.3%; the university rounds the gain to ''about 30% more accurate''"]', '["https://slcl.illinois.edu/news/2024-10-21t201245/automatic-speech-recognition-learned-understand-people-parkinsons-disease"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://news.mit.edu/2020/artificial-intelligence-identifies-new-antibiotic-0220', 'AI finds halicin, a new kind of antibiotic', 'A team at MIT trained a deep learning model to predict which molecules kill bacteria and used it to pick out a compound they named halicin. In lab tests it killed many drug-resistant bacteria, and it cleared resistant infections in mice. The work was published in Cell in February 2020; it has not been tested in people.', 'in_the_lab', '["health", "other"]', 'halicin-antibiotic', 'health', 'other', 12, 'The AI picked the compound out by predicting which molecules kill bacteria, and it worked on bacteria that resist existing drugs.', '["Lab tests and mice only. It has never been tested in people."]', '["https://news.mit.edu/2020/artificial-intelligence-identifies-new-antibiotic-0220", "https://doi.org/10.1016/j.cell.2020.01.021"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.nasa.gov/news-release/artificial-intelligence-nasa-data-used-to-discover-eighth-planet-circling-distant-star/', 'AI finds an eighth planet around a distant star', 'A Google engineer and a NASA-funded astronomer trained a neural network on 15,000 signals from NASA''s Kepler space telescope and used it to search for planets earlier methods had missed. It found Kepler-90i, a hot, rocky world and the eighth planet known around the star Kepler-90. That tied the system with our own for the most known planets around a single star.', 'in_the_lab', '["space", "other"]', 'kepler-90-eighth-planet', 'space', 'other', 12, 'The AI found a planet in telescope data that earlier searches had already been through and missed.', '["From 2017."]', '["https://www.nasa.gov/news-release/artificial-intelligence-nasa-data-used-to-discover-eighth-planet-circling-distant-star/"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://doi.org/10.1038/s41586-023-06825-8', 'AI and satellites show that three quarters of the world''s big fishing boats were not on public maps', 'A team led by the non-profit Global Fishing Watch used AI to search five years of satellite pictures of the world''s coastal waters, from 2017 to 2021, for ships. They found that between 72% and 76% of industrial fishing vessels do not show up in public tracking systems, with much of that fishing around South Asia, Southeast Asia and Africa. The study was published in the journal Nature.', 'in_the_lab', '["climate_and_nature", "vision"]', 'ai-maps-hidden-fishing-fleets', 'climate_and_nature', 'vision', 12, 'AI did the looking across far more satellite pictures than a team of people can get through, giving governments and researchers their first full picture of where industrial fishing really happens.', '["Not being on public tracking is not the same as fishing illegally. Many boats are not required to broadcast their position.", "This is a map of the problem, not a fix. The paper does not report any change in fishing as a result.", "The figure is a range, 72% to 76%, and covers coastal waters, not every part of the ocean."]', '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:10.1038/s41586-023-06825-8&resultType=core&format=json"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://www.jpl.nasa.gov/news/new-deep-learning-method-adds-301-planets-to-keplers-total-count', 'NASA''s ExoMiner AI adds 301 planets to the list of known worlds', 'A NASA team built an AI called ExoMiner and set it to work on a pile of possible planets spotted by the Kepler space telescope that nobody had been able to confirm. Running on NASA''s Pleiades supercomputer, it validated 301 of them as real planets, adding them to the 4,569 already on the list. The results were published in The Astrophysical Journal.', 'in_the_lab', '["space", "other"]', 'exominer-301-exoplanets', 'space', 'other', 12, 'ExoMiner learned from earlier confirmed planets and false alarms how to tell a real planet from an impostor, and it cleared a backlog that human experts had not been able to get through.', '["These planets were ''validated'', meaning shown by statistics to be very likely real, which NASA treats as different from ''confirmed'' by several kinds of observation.", "Kepler had already detected all 301 as candidates. The AI did not find new signals.", "NASA says none of the 301 is thought to be Earth-like or in the zone where liquid water is possible."]', '["https://www.jpl.nasa.gov/news/new-deep-learning-method-adds-301-planets-to-keplers-total-count"]');
INSERT INTO evergreen (url, title, summary, stage, tags, slug, topic, technology, score, why_its_good, careful, sources) VALUES ('https://greenbankobservatory.org/press-release/artificial-intelligence-uncovers-72-new-fast-radio-bursts-in-gbts-breakthrough-listen-data/', 'AI finds 72 mysterious radio flashes from deep space that astronomers had missed', 'Fast radio bursts are split-second flashes of radio waves from distant galaxies, and nobody is sure what makes them. Astronomers had already found 21 bursts in five hours of recordings of one source, about 3 billion light years away, made with the Green Bank Telescope in West Virginia. Gerry Zhang, a PhD student at the University of California, Berkeley, trained an AI on those and ran it over the same recordings, and it found 72 more.', 'in_the_lab', '["space", "other"]', 'ai-finds-72-missed-radio-bursts', 'space', 'other', 12, 'The AI caught faint flashes that the standard search had missed in data that had already been combed, giving astronomers 93 bursts from one source to study instead of 21.', '["The 72 bursts were found in existing recordings from 26 August 2017, not in new observations.", "The work was done within Breakthrough Listen, a project that searches for signs of intelligent life. Nothing here suggests aliens.", "The finding does not explain what causes the bursts."]', '["https://greenbankobservatory.org/press-release/artificial-intelligence-uncovers-72-new-fast-radio-bursts-in-gbts-breakthrough-listen-data/", "https://arxiv.org/abs/1809.03043"]');
